import { describe, expect, it, vi } from 'vitest'
import { ApiError, createIssue, deleteIssue, setStatus, updateIssue } from '../api'
import { installFakeApi, jsonResponse, makeIssue } from './fakeApi'

const draft = {
  title: 'Dark mode flickers',
  description: 'It flashes white first',
  stepsToReproduce: 'Turn on dark mode and reload',
  priority: 'high' as const,
}

describe('createIssue', () => {
  it('POSTs the draft as JSON to /issues and returns the new issue', async () => {
    const { fetchMock } = installFakeApi()

    const created = await createIssue(draft)

    const [url, init] = fetchMock.mock.calls[0]!
    expect(url).toBe('/issues')
    expect(init?.method).toBe('POST')
    expect(new Headers(init?.headers).get('Content-Type')).toBe('application/json')
    expect(JSON.parse(String(init?.body))).toEqual(draft)
    expect(created.title).toBe('Dark mode flickers')
    expect(created.status).toBe('open')
    expect(created._id).toBeTruthy()
  })

  it('keeps the field-by-field problems when the server answers 400', async () => {
    const body = {
      error: 'ValidationFailed',
      details: [
        { path: 'title', message: 'Title is required' },
        { path: 'priority', message: 'Invalid option' },
      ],
    }
    vi.stubGlobal('fetch', vi.fn(async () => jsonResponse(body, 400)))

    const error = await createIssue(draft).catch((e: unknown) => e)

    expect(error).toBeInstanceOf(ApiError)
    expect((error as ApiError).status).toBe(400)
    expect((error as ApiError).message).toBe('ValidationFailed')
    expect((error as ApiError).details).toEqual(body.details)
  })

  it('has an empty details list when the server sent none', async () => {
    vi.stubGlobal('fetch', vi.fn(async () => jsonResponse({ error: 'Your role may not issue:create' }, 403)))

    const error = await createIssue(draft).catch((e: unknown) => e)

    expect((error as ApiError).status).toBe(403)
    expect((error as ApiError).details).toEqual([])
  })
})

describe('updateIssue', () => {
  it('PATCHes /issues/:id with only the fields it was given', async () => {
    const { fetchMock, issues } = installFakeApi()
    const id = issues[0]!._id

    const updated = await updateIssue(id, { title: 'A better title' })

    const [url, init] = fetchMock.mock.calls[0]!
    expect(url).toBe(`/issues/${id}`)
    expect(init?.method).toBe('PATCH')
    expect(JSON.parse(String(init?.body))).toEqual({ title: 'A better title' })
    expect(updated.title).toBe('A better title')
  })
})

describe('setStatus', () => {
  it('PATCHes /issues/:id/status with the new status', async () => {
    const { fetchMock, issues } = installFakeApi()
    const id = issues[0]!._id

    const updated = await setStatus(id, 'closed')

    const [url, init] = fetchMock.mock.calls[0]!
    expect(url).toBe(`/issues/${id}/status`)
    expect(init?.method).toBe('PATCH')
    expect(JSON.parse(String(init?.body))).toEqual({ status: 'closed' })
    expect(updated.status).toBe('closed')
  })
})

describe('deleteIssue', () => {
  it('sends DELETE /issues/:id and resolves with nothing when the server answers 204', async () => {
    const { fetchMock, issues } = installFakeApi([makeIssue(1), makeIssue(2)])
    const id = issues[0]!._id

    const result = await deleteIssue(id)

    const [url, init] = fetchMock.mock.calls[0]!
    expect(url).toBe(`/issues/${id}`)
    expect(init?.method).toBe('DELETE')
    expect(result).toBeUndefined()
    expect(issues).toHaveLength(1)
  })

  it('throws an ApiError with the server message when the server says no', async () => {
    installFakeApi([makeIssue(1)], { failures: { 'DELETE /issues/000000000000000000000001': 403 } })

    const error = await deleteIssue('000000000000000000000001').catch((e: unknown) => e)

    expect(error).toBeInstanceOf(ApiError)
    expect((error as ApiError).status).toBe(403)
    expect((error as ApiError).message).toBe('Your role may not do that')
  })
})
